Object.assign(hi,{demoRequiresGuest:'डेमो डेटा अलग रहता है। इसे खोलने के लिए साइन आउट करके “बिना साइन अप डेमो आज़माएँ” चुनें।',sampleInsightFictional:'नमूना जानकारी (काल्पनिक डेटा)',aboutDataHeading:'डेटा, सहमति और गोपनीयता',aboutDataStored:'यह डेमो आपकी प्रोफ़ाइल, सहमति विकल्प, चेक-इन, चक्र प्रविष्टियाँ, फ़ॉलो-अप, पासपोर्ट प्रारूप और डायरी को इसी डिवाइस के localStorage में रखता है।',aboutDataNeverSent:'इस स्थानीय डेमो में आपके स्वास्थ्य रिकॉर्ड और डायरी किसी सर्वर, बैकएंड या AI सेवा को नहीं भेजे जाते। ऐप Google Fonts का अनुरोध करता है; उसमें सामान्य कनेक्शन जानकारी जाती है, स्वास्थ्य रिकॉर्ड नहीं। PDF इसी डिवाइस पर बनती है।',aboutConsentToggles:'“मेरे चेक-इन सहेजें” विकल्प अभी केवल Cycle पेज के बदलावों को नियंत्रित करता है। बंद होने पर भी अन्य रिकॉर्ड और सेटिंग्स इसी डिवाइस पर सहेजी जाती हैं। AI समझाने का विकल्प सहेजा जाता है, लेकिन कोई AI जुड़ा नहीं है। पासपोर्ट यहीं दिखता है और केवल आपके डाउनलोड किए PDF में जाता है; साझा करने की कोई सेवा जुड़ी नहीं है।',aboutExportDelete:'Export इस खाते के स्थानीय डेटा की JSON प्रति डाउनलोड करता है। “सब कुछ हटाएँ” ऐप डेटा साफ़ करता है; “मेरा खाता और डेटा हटाएँ” स्थानीय खाता और उससे जुड़ा डेटा भी हटाता है।',aboutDemoAuth:'डेमो साइन-इन और खाते इसी डिवाइस पर रहते हैं और इसे इस्तेमाल करने वाला कोई भी व्यक्ति बदल सकता है। पासवर्ड हैश किए जाते हैं, पर यह उत्पादन-स्तर की सुरक्षा नहीं है। वास्तविक या बहुत संवेदनशील जानकारी न डालें।',aboutSafetyHeading:'सुरक्षा और सीमाएँ',aboutSafetyRules:'सुरक्षा और पैटर्न नियम डेमो नियम हैं, जिनकी चिकित्सकीय समीक्षा नहीं हुई है। वे जोखिम चूक सकते हैं या अनावश्यक चेतावनी दिखा सकते हैं।',aboutSafetyAi:'अभी कोई AI सेवा जुड़ी नहीं है। भविष्य में AI की व्याख्या जोड़ी गई तो वह पैटर्न समझा सकती है, लेकिन सुरक्षा की तात्कालिकता नहीं बदल सकती।',aboutValidationHeading:'सत्यापन योजना',aboutValidationPlan:'योजना में है, पूरा नहीं हुआ: चिकित्सकों से नियमों की समीक्षा, प्रतिनिधि उपयोगकर्ताओं के साथ उपयोगिता परीक्षण, और WCAG सुलभता ऑडिट।'});
Object.assign(mr,{demoRequiresGuest:'डेमो माहिती वेगळी राहते. ती उघडण्यासाठी साइन आउट करून “साइन अप न करता डेमो वापरून पहा” निवडा.',sampleInsightFictional:'नमुना निरीक्षण (काल्पनिक माहिती)',aboutDataHeading:'माहिती, संमती आणि गोपनीयता',aboutDataStored:'हा डेमो तुमची प्रोफाइल, संमतीचे पर्याय, चेक-इन, सायकल नोंदी, फॉलो-अप, पासपोर्ट मसुदा आणि डायरी याच डिव्हाइसवरील localStorage मध्ये ठेवतो.',aboutDataNeverSent:'या स्थानिक डेमोमध्ये तुमचे आरोग्य रेकॉर्ड आणि डायरी सर्व्हर, बॅकएंड किंवा AI सेवेकडे पाठवले जात नाहीत. अॅप Google Fonts मागवते; त्या विनंतीत सामान्य कनेक्शन माहिती जाते, आरोग्य रेकॉर्ड नाहीत. PDF याच डिव्हाइसवर तयार होते.',aboutConsentToggles:'“माझे चेक-इन जतन करा” हा पर्याय सध्या फक्त Cycle पेजवरील बदल नियंत्रित करतो. तो बंद असला तरी इतर नोंदी आणि सेटिंग्ज याच डिव्हाइसवर जतन होतात. AI स्पष्टीकरणाचा पर्याय जतन केला जातो, पण AI जोडलेले नाही. पासपोर्ट इथेच दिसतो आणि तुम्ही डाउनलोड करण्याचे निवडलेले PDF मध्येच समाविष्ट होतो; शेअरिंग सेवा जोडलेली नाही.',aboutExportDelete:'Export या खात्यातील स्थानिक माहितीची JSON प्रत डाउनलोड करते. “सर्व काही हटवा” अॅपची माहिती साफ करते; “माझे खाते आणि माहिती हटवा” स्थानिक खाते व त्याच्याशी संबंधित माहितीही काढते.',aboutDemoAuth:'डेमो साइन-इन आणि खाती याच डिव्हाइसवर साठवली जातात आणि ते वापरणारी व्यक्ती ती बदलू शकते. पासवर्डचे हॅश केले जातात, पण ही उत्पादन-स्तराची सुरक्षा नाही. खरी किंवा अतिसंवेदनशील माहिती वापरू नका.',aboutSafetyHeading:'सुरक्षा आणि मर्यादा',aboutSafetyRules:'सुरक्षा आणि पॅटर्न जुळवण्याचे नियम डेमो नियम आहेत; त्यांची वैद्यकीय तपासणी झालेली नाही. ते धोका ओळखू शकत नाहीत किंवा अनावश्यक इशारा देऊ शकतात.',aboutSafetyAi:'सध्या AI सेवा जोडलेली नाही. भविष्यात AI स्पष्टीकरण जोडले तरी ते पॅटर्न समजावू शकते; सुरक्षा तातडीची पातळी बदलू शकत नाही.',aboutValidationHeading:'सत्यापन योजना',aboutValidationPlan:'नियोजित आहे, पूर्ण झालेले नाही: नियमांची चिकित्सकांकडून समीक्षा, प्रतिनिधी वापरकर्त्यांसह उपयोगिता चाचणी, आणि WCAG सुलभता ऑडिट.'});
